package in.pocketwise.widget;
import android.app.Activity; import android.os.Bundle; import android.webkit.WebView; import android.webkit.WebViewClient; import android.webkit.JavascriptInterface; import android.content.Context; import android.appwidget.AppWidgetManager; import android.content.ComponentName; import org.json.JSONObject;
public class MainActivity extends Activity { WebView web; @Override public void onCreate(Bundle b){super.onCreate(b); web=new WebView(this); web.getSettings().setJavaScriptEnabled(true); web.addJavascriptInterface(new PocketBridge(this),"PocketWiseNative"); web.setWebViewClient(new WebViewClient()); setContentView(web); web.loadUrl("https://nithan.in/PocketWise/"); } public static class PocketBridge { Context c; PocketBridge(Context x){c=x.getApplicationContext();} @JavascriptInterface public void updateWidget(String balance,String week){ c.getSharedPreferences("pw_widget",0).edit().putString("balance",balance).putString("week",week).apply(); PocketWiseWidgetProvider.updateAll(c); } }}